"""生成阶段 C 首次迁移草案；已交付后不得重跑覆盖，后续变更追加新版本。"""
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]/'backend/src/main/resources/db/migration'
COMMON='''  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
'''

def table(name,fields):
    return f'CREATE TABLE {name} (\n'+COMMON+'  '+',\n  '.join(fields)+ '\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;\n\n'

def fk(field,target):
    return f'FOREIGN KEY ({field}) REFERENCES {target}(id) ON DELETE RESTRICT'

def write(version,content):
    path=ROOT/version
    with path.open('x',encoding='utf-8') as output: output.write(content)

def main():
    content='-- 新增阶段 C 结构；无账号、口令或业务种子。\n'
    content+=table('file_object',["owner_user_id BIGINT UNSIGNED NOT NULL","shop_id BIGINT UNSIGNED NULL","purpose VARCHAR(24) COLLATE utf8mb4_bin NOT NULL","visibility VARCHAR(16) COLLATE utf8mb4_bin NOT NULL","storage_key VARCHAR(255) COLLATE utf8mb4_bin NOT NULL UNIQUE","mime_type VARCHAR(40) NOT NULL","byte_size BIGINT UNSIGNED NOT NULL","sha256 VARCHAR(64) COLLATE utf8mb4_bin NOT NULL","status VARCHAR(16) COLLATE utf8mb4_bin NOT NULL DEFAULT 'ACTIVE'",fk('owner_user_id','iam_user'),fk('shop_id','shop'),"CHECK(purpose IN ('BOOK_COVER','AFTER_SALE_EVIDENCE'))","CHECK((purpose='BOOK_COVER' AND visibility='PUBLIC') OR (purpose='AFTER_SALE_EVIDENCE' AND visibility='PRIVATE'))","CHECK(status IN ('ACTIVE','DELETED'))","INDEX ix_file_owner_created(owner_user_id,created_at)"])
    content+=table('category',["parent_id BIGINT UNSIGNED NULL","name VARCHAR(50) NOT NULL","sort_order INT NOT NULL DEFAULT 0","status VARCHAR(16) COLLATE utf8mb4_bin NOT NULL DEFAULT 'ACTIVE'",fk('parent_id','category'),"CHECK(status IN ('ACTIVE','DISABLED'))","INDEX ix_category_parent_sort(parent_id,sort_order)"])
    content+=table('book',["isbn VARCHAR(13) COLLATE utf8mb4_bin NOT NULL UNIQUE","title VARCHAR(200) NOT NULL","author VARCHAR(200) NOT NULL","publisher VARCHAR(120) NOT NULL","publication_date DATE NULL","category_id BIGINT UNSIGNED NOT NULL","description VARCHAR(5000) NOT NULL","cover_file_id BIGINT UNSIGNED NULL","status VARCHAR(16) COLLATE utf8mb4_bin NOT NULL DEFAULT 'ACTIVE'",fk('category_id','category'),fk('cover_file_id','file_object'),"CHECK(status IN ('ACTIVE','DISABLED'))","INDEX ix_book_category_status_id(category_id,status,id)"])
    content+=table('product',["shop_id BIGINT UNSIGNED NOT NULL","book_id BIGINT UNSIGNED NOT NULL","description VARCHAR(5000) NOT NULL","status VARCHAR(16) COLLATE utf8mb4_bin NOT NULL DEFAULT 'DRAFT'","featured TINYINT NOT NULL DEFAULT 0","version INT UNSIGNED NOT NULL DEFAULT 1",fk('shop_id','shop'),fk('book_id','book'),"UNIQUE(shop_id,book_id)","CHECK(status IN ('DRAFT','ON_SALE','OFF_SHELF'))","CHECK(featured IN (0,1))","INDEX ix_product_shop_status(shop_id,status)","INDEX ix_product_status_featured(status,featured)"])
    content+=table('sku',["product_id BIGINT UNSIGNED NOT NULL UNIQUE","sku_code VARCHAR(64) COLLATE utf8mb4_bin NOT NULL UNIQUE","sale_price DECIMAL(12,2) NOT NULL","version INT UNSIGNED NOT NULL DEFAULT 1",fk('product_id','product'),"CHECK(sale_price>0)"])
    content+=table('inventory',["sku_id BIGINT UNSIGNED NOT NULL UNIQUE","on_hand INT UNSIGNED NOT NULL DEFAULT 0","reserved INT UNSIGNED NOT NULL DEFAULT 0","version INT UNSIGNED NOT NULL DEFAULT 1",fk('sku_id','sku'),"CHECK(reserved<=on_hand)"])
    content+=table('cart_item',["user_id BIGINT UNSIGNED NOT NULL","sku_id BIGINT UNSIGNED NOT NULL","quantity INT UNSIGNED NOT NULL","selected TINYINT NOT NULL DEFAULT 1",fk('user_id','iam_user'),fk('sku_id','sku'),"UNIQUE(user_id,sku_id)","CHECK(quantity BETWEEN 1 AND 99)","CHECK(selected IN (0,1))"])
    content+=table('idempotency_record',["user_id BIGINT UNSIGNED NOT NULL","operation_id VARCHAR(40) COLLATE utf8mb4_bin NOT NULL","idempotency_key VARCHAR(64) COLLATE utf8mb4_bin NOT NULL","request_hash VARCHAR(64) COLLATE utf8mb4_bin NOT NULL","status VARCHAR(16) COLLATE utf8mb4_bin NOT NULL DEFAULT 'PROCESSING'","resource_type VARCHAR(40) COLLATE utf8mb4_bin NULL","resource_id VARCHAR(64) COLLATE utf8mb4_bin NULL","response_snapshot JSON NULL","replay_until DATETIME(3) NOT NULL","retain_until DATETIME(3) NOT NULL",fk('user_id','iam_user'),"UNIQUE(user_id,operation_id,idempotency_key)","CHECK(status IN ('PROCESSING','SUCCEEDED'))","INDEX ix_idempotency_retention(retain_until)"])
    write('V5__catalog_files_inventory_cart.sql',content)
    content='-- 为库存流水和凭证鉴权建立真实外键依赖的空结构，不开放交易/售后/评价写接口，不造业务样本。\n'
    content+=table('checkout_preview',["user_id BIGINT UNSIGNED NOT NULL","address_id BIGINT UNSIGNED NOT NULL","items_snapshot JSON NOT NULL","address_version_hash VARCHAR(64) COLLATE utf8mb4_bin NOT NULL","amount DECIMAL(12,2) NOT NULL","expires_at DATETIME(3) NOT NULL","used_at DATETIME(3) NULL",fk('user_id','iam_user'),fk('address_id','user_address'),"CHECK(amount>=0)","INDEX ix_preview_user_expires(user_id,expires_at)"])
    content+=table('checkout_batch',["batch_no VARCHAR(40) COLLATE utf8mb4_bin NOT NULL UNIQUE","user_id BIGINT UNSIGNED NOT NULL","preview_id BIGINT UNSIGNED NOT NULL UNIQUE","total_amount DECIMAL(12,2) NOT NULL",fk('user_id','iam_user'),fk('preview_id','checkout_preview'),"CHECK(total_amount>=0)","INDEX ix_batch_user_created(user_id,created_at)"])
    content+=table('trade_order',["order_no VARCHAR(40) COLLATE utf8mb4_bin NOT NULL UNIQUE","batch_id BIGINT UNSIGNED NOT NULL","user_id BIGINT UNSIGNED NOT NULL","shop_id BIGINT UNSIGNED NOT NULL","status VARCHAR(24) COLLATE utf8mb4_bin NOT NULL DEFAULT 'PENDING_PAYMENT'","financial_status VARCHAR(24) COLLATE utf8mb4_bin NOT NULL DEFAULT 'UNPAID'","goods_amount DECIMAL(12,2) NOT NULL","freight_amount DECIMAL(12,2) NOT NULL DEFAULT 0.00","payable_amount DECIMAL(12,2) NOT NULL","refunded_amount DECIMAL(12,2) NOT NULL DEFAULT 0.00","receiver_name VARCHAR(40) NOT NULL","receiver_phone VARCHAR(32) NOT NULL","receiver_address VARCHAR(300) NOT NULL","expires_at DATETIME(3) NOT NULL",*[f'{name}_at DATETIME(3) NULL' for name in ['paid','shipped','completed','closed']],"close_reason VARCHAR(300) NULL","version INT UNSIGNED NOT NULL DEFAULT 1",fk('batch_id','checkout_batch'),fk('user_id','iam_user'),fk('shop_id','shop'),"UNIQUE(batch_id,shop_id)","CHECK(status IN ('PENDING_PAYMENT','PAID','CLOSING','CANCELLED','SHIPPED','COMPLETED','CLOSED_REFUND'))","CHECK(financial_status IN ('UNPAID','PAID','PARTIALLY_REFUNDED','REFUNDED'))","CHECK(goods_amount>=0 AND freight_amount>=0 AND payable_amount=goods_amount+freight_amount AND refunded_amount BETWEEN 0 AND payable_amount)","INDEX ix_order_user_created(user_id,created_at,id)","INDEX ix_order_shop_status_created(shop_id,status,created_at)","INDEX ix_order_status_expires(status,expires_at)","INDEX ix_order_completed(completed_at)"])
    content+=table('order_item',["order_id BIGINT UNSIGNED NOT NULL","sku_id BIGINT UNSIGNED NOT NULL","book_id BIGINT UNSIGNED NOT NULL","product_id BIGINT UNSIGNED NOT NULL","book_title VARCHAR(200) NOT NULL","isbn VARCHAR(13) COLLATE utf8mb4_bin NOT NULL","cover_storage_key VARCHAR(255) COLLATE utf8mb4_bin NULL","sku_code VARCHAR(64) COLLATE utf8mb4_bin NOT NULL","unit_price DECIMAL(12,2) NOT NULL","quantity INT UNSIGNED NOT NULL","line_amount DECIMAL(12,2) NOT NULL","refunded_quantity INT UNSIGNED NOT NULL DEFAULT 0","refunded_amount DECIMAL(12,2) NOT NULL DEFAULT 0.00",*[fk(f'{name}_id',name if name!='order' else 'trade_order') for name in ['order','sku','book','product']],"UNIQUE(order_id,sku_id)","CHECK(quantity BETWEEN 1 AND 99 AND unit_price>0 AND line_amount=unit_price*quantity AND refunded_quantity<=quantity AND refunded_amount BETWEEN 0 AND line_amount)"])
    content+=table('after_sale',["after_sale_no VARCHAR(40) COLLATE utf8mb4_bin NOT NULL UNIQUE","order_id BIGINT UNSIGNED NOT NULL","order_item_id BIGINT UNSIGNED NOT NULL","user_id BIGINT UNSIGNED NOT NULL","type VARCHAR(24) COLLATE utf8mb4_bin NOT NULL","quantity INT UNSIGNED NOT NULL","requested_amount DECIMAL(12,2) NOT NULL","reason VARCHAR(500) NOT NULL","status VARCHAR(24) COLLATE utf8mb4_bin NOT NULL DEFAULT 'REQUESTED'","reviewed_by BIGINT UNSIGNED NULL","reviewed_at DATETIME(3) NULL","review_note VARCHAR(500) NULL","return_deadline DATETIME(3) NULL","return_carrier VARCHAR(50) NULL","return_tracking_no VARCHAR(80) COLLATE utf8mb4_bin NULL","received_by BIGINT UNSIGNED NULL","received_at DATETIME(3) NULL","restock_quantity INT UNSIGNED NOT NULL DEFAULT 0","inspection_note VARCHAR(500) NULL","active_order_item_id BIGINT UNSIGNED GENERATED ALWAYS AS (CASE WHEN status IN ('REQUESTED','APPROVED','RETURNING','RECEIVED','REFUNDING') THEN order_item_id ELSE NULL END) STORED UNIQUE",fk('order_id','trade_order'),fk('order_item_id','order_item'),fk('user_id','iam_user'),fk('reviewed_by','iam_user'),fk('received_by','iam_user'),"CHECK(type IN ('REFUND_ONLY','RETURN_REFUND'))","CHECK(status IN ('REQUESTED','APPROVED','RETURNING','RECEIVED','REFUNDING','REJECTED','CANCELLED','COMPLETED','EXPIRED'))","CHECK(quantity BETWEEN 1 AND 99 AND requested_amount>0 AND restock_quantity IN (0,quantity))","INDEX ix_after_sale_item_status(order_item_id,status)"])
    content+=table('after_sale_evidence',["after_sale_id BIGINT UNSIGNED NOT NULL","file_id BIGINT UNSIGNED NOT NULL",fk('after_sale_id','after_sale'),fk('file_id','file_object'),"UNIQUE(after_sale_id,file_id)"])
    content+=table('review',["order_item_id BIGINT UNSIGNED NOT NULL UNIQUE","user_id BIGINT UNSIGNED NOT NULL","product_id BIGINT UNSIGNED NOT NULL","rating TINYINT UNSIGNED NOT NULL","content VARCHAR(1000) NOT NULL","status VARCHAR(16) COLLATE utf8mb4_bin NOT NULL DEFAULT 'VISIBLE'","moderated_by BIGINT UNSIGNED NULL","moderation_reason VARCHAR(300) NULL",fk('order_item_id','order_item'),fk('user_id','iam_user'),fk('product_id','product'),fk('moderated_by','iam_user'),"CHECK(rating BETWEEN 1 AND 5)","CHECK(status IN ('VISIBLE','HIDDEN'))","INDEX ix_review_product_status_created(product_id,status,created_at)"])
    content+=table('inventory_movement',["sku_id BIGINT UNSIGNED NOT NULL","order_item_id BIGINT UNSIGNED NULL","after_sale_id BIGINT UNSIGNED NULL","movement_type VARCHAR(32) COLLATE utf8mb4_bin NOT NULL","business_key VARCHAR(100) COLLATE utf8mb4_bin NOT NULL UNIQUE","on_hand_delta INT NOT NULL","reserved_delta INT NOT NULL","on_hand_after INT UNSIGNED NOT NULL","reserved_after INT UNSIGNED NOT NULL","reason VARCHAR(300) NOT NULL","operator_id BIGINT UNSIGNED NULL","trace_id VARCHAR(64) COLLATE utf8mb4_bin NOT NULL",fk('sku_id','sku'),fk('order_item_id','order_item'),fk('after_sale_id','after_sale'),fk('operator_id','iam_user'),"CHECK(movement_type IN ('MANUAL_ADJUST','RESERVE','COMMIT','RELEASE','REFUND_RESTOCK','RETURN_RESTOCK'))","CHECK(reserved_after<=on_hand_after)","INDEX ix_movement_sku_created(sku_id,created_at)"])
    content+="CREATE TRIGGER inventory_movement_reject_update BEFORE UPDATE ON inventory_movement FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='inventory_movement is append-only';\nCREATE TRIGGER inventory_movement_reject_delete BEFORE DELETE ON inventory_movement FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='inventory_movement is append-only';\n"
    write('V6__movement_and_evidence_foreign_keys.sql',content)

if __name__=='__main__': main()
